/* ============================================
   Volta Studio — Design System
   Minimal, editorial, warm
   ============================================ */

/* ---- CSS Variables ---- */
:root {
  --bg: #F5F2ED;
  --bg-warm: #EDE9E3;
  --text: #1A1A1A;
  --text-muted: #6B6560;
  --accent-terracotta: #C4715A;
  --accent-sage: #8A9B7A;
  --accent-sand: #D4B896;
  --accent-clay: #B87A5C;
  --accent-olive: #7A8568;

  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 4rem;
  --space-xl: 6rem;
  --space-2xl: 8rem;
  --space-3xl: 12rem;

  --max-content: 72rem;
  --max-reading: 42rem;

  --transition: 0.3s ease;
}

/* ---- Reset & Base ---- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  color: var(--text);
  background-color: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* ---- Typography ---- */
.heading-display {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.02em;
}

.heading-xl {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 8vw, 7rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.heading-lg {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.heading-md {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 600;
  line-height: 1.2;
}

.body-lg {
  font-size: clamp(1.1rem, 1.5vw, 1.35rem);
  line-height: 1.7;
  color: var(--text-muted);
}

.body-md {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text-muted);
}

.label {
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
}

/* ---- Layout ---- */
.container {
  width: 100%;
  max-width: var(--max-content);
  margin: 0 auto;
  padding-left: var(--space-md);
  padding-right: var(--space-md);
}

.container-narrow {
  width: 100%;
  max-width: var(--max-reading);
  margin: 0 auto;
  padding-left: var(--space-md);
  padding-right: var(--space-md);
}

.section {
  padding-top: var(--space-2xl);
  padding-bottom: var(--space-2xl);
}

.section-sm {
  padding-top: var(--space-lg);
  padding-bottom: var(--space-lg);
}

/* ---- Header / Navigation ---- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  padding: var(--space-sm) var(--space-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(245, 242, 237, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-desktop {
  display: flex;
  gap: var(--space-md);
}

.nav-desktop a {
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  position: relative;
  padding-bottom: 2px;
}

.nav-desktop a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width var(--transition);
}

.nav-desktop a:hover::after,
.nav-desktop a.active::after {
  width: 100%;
}

/* Mobile menu toggle */
.menu-toggle {
  display: none;
  width: 32px;
  height: 32px;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 110;
}

.menu-toggle span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.3s ease;
  border-radius: 1px;
}

.menu-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(6.5px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-6.5px) rotate(-45deg);
}

/* Mobile overlay */
.mobile-nav {
  position: fixed;
  inset: 0;
  background: var(--bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
  z-index: 105;
}

.mobile-nav.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-nav a {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 6vw, 3.5rem);
  font-weight: 600;
  letter-spacing: -0.02em;
  transition: color var(--transition);
}

.mobile-nav a:hover {
  color: var(--accent-terracotta);
}

@media (max-width: 768px) {
  .nav-desktop {
    display: none;
  }
  .menu-toggle {
    display: flex;
  }
}

/* ---- Marquee ---- */
.marquee-section {
  overflow: hidden;
  padding-top: var(--space-xl);
  padding-bottom: var(--space-xl);
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  will-change: transform;
  padding: var(--space-xs) 0;
}

.marquee-track {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding-right: var(--space-sm);
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 4vw, 3rem);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--text);
  opacity: 0.25;
  flex-shrink: 0;
}

.marquee-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text);
  opacity: 0.2;
  flex-shrink: 0;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-row:nth-child(1) .marquee-track {
  animation: marquee-left 40s linear infinite;
}

.marquee-row:nth-child(2) .marquee-track {
  animation: marquee-right 45s linear infinite;
}

.marquee-row:nth-child(3) .marquee-track {
  animation: marquee-left 50s linear infinite;
}

/* ---- Media Showcase ---- */
.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-sm);
  margin-top: var(--space-xl);
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
}

@media (max-width: 768px) {
  .media-showcase {
    grid-template-columns: 1fr;
  }
}

/* ---- Clients Grid ---- */
.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl) var(--space-lg);
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.client-card p {
  font-size: 0.95rem;
  line-height: 1.6;
  color: var(--text-muted);
}

@media (max-width: 900px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .clients-grid {
    grid-template-columns: 1fr;
  }
}

/* ---- Services ---- */
.service-item {
  margin-bottom: var(--space-lg);
}

.service-item h3 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.service-item p {
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--text-muted);
}

/* ---- Divider ---- */
.divider {
  width: 100%;
  height: 1px;
  background: var(--text);
  opacity: 0.1;
  margin: var(--space-xl) 0;
}

/* ---- Contact ---- */
.contact-hero {
  min-height: 60vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.contact-links {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-sm);
}

.contact-links a {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  font-weight: 600;
  position: relative;
  padding-bottom: 2px;
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width var(--transition);
}

.contact-links a:hover::after {
  width: 100%;
}

/* ---- Footer ---- */
.site-footer {
  padding: var(--space-lg) var(--space-md);
  text-align: center;
}

.site-footer p {
  font-size: 0.8rem;
  color: var(--text-muted);
  letter-spacing: 0.05em;
}

/* ---- Utility ---- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.text-center {
  text-align: center;
}

.mt-sm { margin-top: var(--space-sm); }
.mt-md { margin-top: var(--space-md); }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }

.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }
